def-hyp(
    list-partial(
        Type.annotation(@A, Set(T@Set.ctxt.T)),
        Type.annotation(@x, S@Topology.ctxt.S)
    ),
    Topology.closurePoint(x, A),
    Logic.forall-typed(
        @U,
        Set(T@Set.ctxt.T),
        Logic.implies(
            Topology.neighborhood(U, x),
            Neq(Set.inter(U, A), Set.emptyset)
        )
    )
)
